161	 *
162	 * **Accepted inputs:**
163	 * - `undefined` / `null` → returns `undefined`
164	 * - `GitCredentialEntry[]` (new format) → validated and returned as-is
165	 * - `Record<string, string>` (old format, hostname→token map) → migrated to
166	 *   `GitCredentialEntry[]` with `id` derived from the hostname in kebab-case
167	 *   and `label` set to the hostname. Colliding IDs get a numeric suffix (`-2`,
168	 *   `-3`, …).
169	 * - An empty array `[]` → returns `[]`
170	 *
171	 * **Validation (new-format arrays):**
172	 * - Every entry must have non-empty `id`, `label`, `host`, and `token` fields.
173	 * - Duplicate `id` values within the array are rejected.
174	 *
175	 * @returns `undefined` when the field is absent or null; otherwise a
176	 *   `GitCredentialEntry[]` (possibly empty).
177	 * @throws {Error} If the value is present but structurally invalid, or if any
178	 *   entry fails validation.
179	 */
180	function parseGitCredentials(value: unknown): GitCredentialEntry[] | undefined {
181	    if (value === undefined || value === null) {
182	        return undefined;
183	    }
184	
185	    // --- New format: array of GitCredentialEntry objects ---
186	    if (Array.isArray(value)) {
187	        // Empty array is valid — treat as "no credentials".
188	        if (value.length === 0) {
189	            return [];
190	        }
191	
192	        const seenIds = new Set<string>();
193	
194	        for (let i = 0; i < value.length; i++) {
195	            const entry = value[i] as Record<string, unknown>;
196	
197	            if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
198	                throw new Error(
199	                    `Configuration error: gitCredentials[${i}] must be a credential object, got ${typeof entry}.`
200	                );
201	            }
202	
203	            for (const field of ['id', 'label', 'host', 'token'] as const) {
204	                const fieldValue = entry[field];
205	                if (typeof fieldValue !== 'string' || fieldValue.trim() === '') {
206	                    throw new Error(
207	                        `Configuration error: gitCredentials[${i}].${field} must be a non-empty string.`
208	                    );
209	                }
210	            }
211	
212	            // Per-field length limits — enforce the same limits as the credential API.
213	            const fieldLimits: Array<['id' | 'label' | 'host' | 'token', number]> = [
214	                ['id', MAX_CREDENTIAL_ID_LENGTH],
215	                ['label', MAX_CREDENTIAL_LABEL_LENGTH],
216	                ['host', MAX_CREDENTIAL_HOST_LENGTH],
217	                ['token', MAX_CREDENTIAL_TOKEN_LENGTH],
218	            ];
219	            for (const [field, maxLen] of fieldLimits) {
220	                const fieldValue = (entry[field] as string).trim();
221	                if (fieldValue.length > maxLen) {
222	                    throw new Error(
223	                        `Configuration error: gitCredentials[${i}].${field} must not exceed ${maxLen} characters (got ${fieldValue.length}).`
224	                    );
225	                }
226	            }
227	
228	            const id = (entry['id'] as string).trim();
229	            if (seenIds.has(id)) {
230	                throw new Error(
231	                    `Configuration error: gitCredentials contains duplicate id "${id}".`
232	                );
233	            }
234	            seenIds.add(id);
235	        }
236	
237	        return value as GitCredentialEntry[];
238	    }
239	
240	    // --- Old format: plain object mapping hostname → token ---

241	    if (typeof value === 'object') {
242	        const legacyMap = value as Record<string, unknown>;
243	        const entries = Object.entries(legacyMap);
244	
245	        // Empty legacy object → return undefined (no credentials configured).
246	        if (entries.length === 0) {
247	            return undefined;
248	        }
249	
250	        const result: GitCredentialEntry[] = [];
251	        const usedIds = new Set<string>();
252	
253	        for (const [index, [host, token]] of entries.entries()) {
254	            if (typeof token !== 'string') {
255	                throw new Error(
256	                    `Configuration error: gitCredentials entry #${index + 1} (legacy format) must have a string value, got ${typeof token}.`
257	                );
258	            }
259	            if (token === '') {
260	                throw new Error(
261	                    `Configuration error: gitCredentials entry #${index + 1} (legacy format) must not have an empty string value.`
262	                );
263	            }
264	
265	            // Derive a kebab-case ID from the hostname.
266	            const baseId = toKebabCase(host);
267	            let candidateId = baseId;
268	            let suffix = 2;
269	            while (usedIds.has(candidateId)) {
270	                candidateId = `${baseId}-${suffix}`;
271	                suffix++;
272	            }
273	            usedIds.add(candidateId);
274	
275	            result.push({
276	                id: candidateId,
277	                label: host,
278	                host,
279	                token,
280	            });
281	        }
282	
283	        return result;
284	    }
285	
286	    throw new Error(
287	        'Configuration error: "gitCredentials" must be an array of credential entries or omitted.'
288	    );
289	}
